import copy, json
from pathlib import Path

steps_path=Path('steps.json'); lessons_path=Path('lessons.json')
steps=json.loads(steps_path.read_text(encoding='utf-8'))
lessons=json.loads(lessons_path.read_text(encoding='utf-8'))
by={s['lesson_id']:s for s in steps['stepsets']}

def set_item(item, **fields):
    item.update(fields)

def append_casual(lesson_id, ru, thai, phonetic, tip):
    s=by[lesson_id]
    if any(i.get('ru')==ru for i in s['items']): return
    template=copy.deepcopy(next(i for i in s['items'] if i.get('kind') in ('phrase','casual','word')))
    for k in list(template):
        if k not in ('order','kind','ru','thai','phonetic','tip'): template[k]=None
    template.update({'order':len(s['items'])+1,'kind':'casual','ru':ru,'thai':thai,'phonetic':phonetic,'tip':tip})
    s['items'].append(template)

def course(cid): return next(c for c in lessons['courses'] if c['course_id']==cid)
def lesson(cid,lid): return next(l for l in course(cid)['lessons'] if l['lesson_id']==lid)
def set_lesson(l, subtitle, outcome, prereq, intro, outline, apply):
    l['subtitle']=subtitle; l['outcomes']=[outcome]; l['prerequisites']=prereq
    l['content']=[{'kind':'intro','text':intro},{'kind':'outline','text':outline},{'kind':'apply','text':apply}]

